const SERVICE_NAMES_EN = { "Госуслуги": "Gosuslugi", "Сбербанк": "Sberbank", "Т-Банк": "T-Bank", "Яндекс": "Yandex" };

let LANG = localStorage.getItem("pult-lang") || "ru";

function t(key, vars) {
  let s = (STRINGS[LANG] && STRINGS[LANG][key]) ?? STRINGS.ru[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ""));
  return s;
}

function plural(n, one, few, many) {
  if (LANG === "en") return n === 1 ? one : many;
  const m10 = n % 10, m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return one;
  if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return few;
  return many;
}

function svcName(name) {
  return LANG === "en" ? (SERVICE_NAMES_EN[name] || name) : name;
}
